def hk_wallTemp(Tbulk, qFlux, h, eps, Ta):
    t0 = Tbulk
    t1 = qFlux
    t2 = h
    t3 = eps
    t4 = Ta
    t5 = (t1 / t2)
    t6 = (t0 + t5)
    t7 = 0
    t8 = np.maximum(t7, t1)
    t9 = 0.01
    t10 = np.maximum(t3, t9)
    t11 = 0.0000000567
    t12 = (t10 * t11)
    t13 = (t8 / t12)
    t14 = np.maximum(t4, t7)
    t15 = (t14 ** 4)
    t16 = (t13 + t15)
    t17 = np.sqrt(np.maximum(t16, 0.0))
    t18 = np.sqrt(np.maximum(t17, 0.0))
    t19 = np.minimum(t6, t18)
    t20 = np.maximum(t0, t19)
    return t20

